#include <bits/stdc++.h>
using namespace std;
const int N=2e5+5,M=5e6+5,MM=25e5;
int n,q,tot,fail[MM],dep[MM],ans;
char s1[M],s2[M];
int tag[MM],fa[MM][22];
unordered_map<int,int>trie[MM];
vector<int>g[MM];
void add()
{
	int now=0;
	for(int i=1;s1[i];i++)
	{
		int p=(s1[i]-'a')*26+s2[i]-'a';
		if(!trie[now][p])
		{
			trie[now][p]=++tot;
			dep[tot]=dep[now]+1;
		}
		now=trie[now][p];
	}
	++tag[now];
}
void getfail()
{
	queue<int>q;
	q.push(0);
	while(!q.empty())
	{
		int x=q.front();q.pop();
		for(auto pp:trie[x])
		{
			int p=pp.first;
			int to=pp.second;
			int now=fail[x];
			while(now&&trie[now].find(p)==trie[now].end())
				now=fail[now];
			if(x&&trie[now].find(p)!=trie[now].end())now=trie[now][p];
			fail[to]=now;
			g[now].push_back(to);
			q.push(to);
		}
	}
}
void dfs(int x)
{
	for(int to:g[x])
	{
		tag[to]+=tag[x];
		fa[to][0]=x;
		for(int i=1;i<=21;i++)
			fa[to][i]=fa[fa[to][i-1]][i-1];
		dfs(to);
	}
}
int read(char *s)
{
	char c;int i=0;
	while((c=getchar())<'a'||c>'z')continue;
	s[++i]=c;
	while((c=getchar())>='a'&&c<='z')s[++i]=c;
	s[i+1]=0;
	return i;
}
int main()
{
	scanf("%d%d",&n,&q);
	for(int i=1;i<=n;i++)
	{
		read(s1),read(s2),add();
	}
	getfail();dfs(0);
	for(int i=1;i<=q;i++)
	{
		int len=read(s1),len2=read(s2);
		if(len!=len2)
		{
			puts("0");continue;
		}
		int l=len+1,r=0;
		for(int i=1;i<=len;i++)
		{
			if(s1[i]!=s2[i])
			{
				l=i-1;break;
			}
		}
		for(int i=len;i;i--)
		{
			if(s1[i]!=s2[i])
			{
				r=i+1;break;
			}
		}
		int now=0,ans=0;
		for(int i=1;i<=len;i++)
		{
			int p=(s1[i]-'a')*26+s2[i]-'a';
			while(now&&trie[now].find(p)==trie[now].end())
				now=fail[now];
			if(trie[now].find(p)!=trie[now].end())now=trie[now][p];
			if(i>=r-1)
			{
				if(dep[now]<i-l)continue;
				int x=now;
				for(int j=21;~j;j--)
					if(dep[fa[x][j]]>=i-l)x=fa[x][j];
				x=fa[x][0];
				ans+=tag[now]-tag[x];
			}
		}
		printf("%d\n",ans);
	}
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define ull unsigned long long
#define B 71
#define N 200209
#define M 5000509
int n,m,typ,len,K[N],ans[N],cnt[M];
ull H[N],HX[M];
string S[N],s1,s2;
map<pair<ull,ull>,int> mp;
struct query{ int num,id; };
struct Trie{
	int V;
	struct node{
		int son[27];
		vector<int> w;
		vector<query> q;
		node(){
			memset(son,0,sizeof(son));
			w.clear(); q.clear();
		}
	};
	vector<node> tr;
	Trie(){
		tr.emplace_back();
		tr.emplace_back();
		tr.emplace_back();
		V = 1;
	}
	inline void ins(int idx,int pre){

		int u = 1;
		for(int i = 0;i < S[idx].size();i++){
			int c = S[idx][i] - 'a' + 1;
			if(!tr[u].son[c]){
				tr.emplace_back();
				tr[u].son[c] = ++V;
			}
			u = tr[u].son[c];
		}
		tr[u].w.emplace_back(pre);
	}
	inline int find(int l){
		int u = 1;
		for(int i = l - 1;i >= 0;i--){
			int c = s1[i] - 'a' + 1;
			if(!tr[u].son[c]) return u;
			u = tr[u].son[c];
		}
		return u;
	}
	inline void dfs(int u){
		for(int i = 0;i < tr[u].w.size();i++) cnt[tr[u].w[i]]++;
		for(int i = 0;i < tr[u].q.size();i++) ans[tr[u].q[i].id] += cnt[tr[u].q[i].num];
		for(int i = 1;i <= 26;i++)
			if(tr[u].son[i]) dfs(tr[u].son[i]);
		for(int i = 0;i < tr[u].w.size();i++) cnt[tr[u].w[i]]--;
	}
} T[N];
inline ull F1(int l,int r){
	ull h = 0;
	for(int i = l;i <= r;i++) h = h * B + (s1[i] - 'a' + 1);
	return h;
}
inline ull F2(int l,int r){
	ull h = 0;
	for(int i = l;i <= r;i++) h = h * B + (s2[i] - 'a' + 1);
	return h;
}
inline void work(){
	cin>>n>>m;
	int tmp = n;
	n = 0;
	H[++len] = 0;
	for(int i = 1;i <= tmp;i++){
		cin>>s1>>s2;
		if(s1 == s2) continue;
		int l = 1e9,r = 0;
		for(int j = 0;j < s1.size();j++)
			if(s1[j] != s2[j]) l = min(l,j),r = max(r,j);
		int u = 0;
		ull res1 = F1(l,r),res2 = F2(l,r);
		if(!mp.count(make_pair(res1,res2)))
			mp[make_pair(res1,res2)] = ++typ;
		u = mp[make_pair(res1,res2)];

		ull h = 0;
		for(int j = r + 1;j < s1.size();j++){
			h = h * B + (s1[j] - 'a' + 1);
			HX[++len] = h;
		}
		n++;
		H[n] = h; S[n] = s1.substr(0,l); K[n] = u;
		reverse(S[n].begin(),S[n].end());

	}
	sort(HX + 1,HX + len + 1);
	len = unique(HX + 1,HX + len + 1) - HX - 1;
	for(int i = 1;i <= n;i++) T[K[i]].ins(i,lower_bound(HX + 1,HX + len + 1,H[i]) - HX);

	for(int i = 1;i <= m;i++){
		cin>>s1>>s2;
        if(s1.size() != s2.size()) continue;
		int l = 1e9,r = 0;
		for(int j = 0;j < s1.size();j++)
			if(s1[j] != s2[j]) l = min(l,j),r = max(r,j);
		ull res1 = F1(l,r),res2 = F2(l,r);
		int idx = mp[make_pair(res1,res2)];
		if(!idx) continue;
		int u = T[idx].find(l);
		ull h = 0;
		T[idx].tr[u].q.emplace_back((query){1,i});
		for(int j = r + 1;j < s1.size();j++){
			h = h * B + (s1[j] - 'a' + 1);
			int tmp = lower_bound(HX + 1,HX + len + 1,h) - HX;
			if(HX[tmp] == h) T[idx].tr[u].q.emplace_back((query){tmp,i});
		}
	}
	for(int i = 1;i <= typ;i++) T[i].dfs(1);
	for(int i = 1;i <= m;i++) cout<<ans[i]<<"\n";
}
signed main(){


	cin.tie(0); cout.tie(0);
	ios::sync_with_stdio(0);
	work();
}
